import React, { lazy, Suspense } from "react";

const WidgetA = lazy(() => import("../components/widget-a"));
const WidgetB = lazy(() => import("../components/widget-b"));
const WidgetC = lazy(() => import("../components/widget-c"));

export default function IndexPage() {
  const loadExtra = (name) => {
    // expression import: never statically resolvable
    import(`../components/extra-${name}`).catch(() => {});
  };

  return (
    <main style={{ fontFamily: "system-ui" }}>
      <h1>Gatsby dynamic import demo</h1>
      <div>
        <Suspense fallback={<div>loading widgets ...</div>}>
          <WidgetA />
          <WidgetB />
          <WidgetC />
        </Suspense>
      </div>
      <button onClick={() => loadExtra("one")}>load extra one</button>
      <button onClick={() => loadExtra("two")}>load extra two</button>
    </main>
  );
}